package com.nigson.commerce.pricing;
import java.util.*;
import java.time.*;
import java.math.*;
import tools.jackson.databind.JsonNode;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.commerce.market.MarketValues;
/** Commercial inputs are explicit. Wire decimals never pass through binary floating point. */
public final class PricingValues {
 private PricingValues(){}
 public record Entry(UUID skuId,String minimumQuantity,String unitAmount){}
 public record Input(String code,String currency,String segment,Instant effectiveFrom,Instant effectiveUntil,List<Entry> entries){public Input{entries=List.copyOf(entries);}}
 public record Book(UUID id,String code,long revision,String currency,String segment,Instant effectiveFrom,Instant effectiveUntil,boolean active,List<Entry> entries,long version){}
 public record Query(String segment,String currency,int page,int size,String sort){public Query{ApiValues.page(page,size);if(segment!=null&&!Set.of("RETAIL","DISTRIBUTOR").contains(segment))throw ApiValues.invalid();if(currency!=null)PricingValues.currency(currency);ApiValues.sort(sort,Set.of("code,asc","code,desc","revision,asc","revision,desc","effectiveFrom,asc","effectiveFrom,desc"));}}
 public record Page(List<Book> items,int page,int size,long totalElements,long totalPages){}
 public record Price(UUID skuId,String unitAmount,String currency,String minimumQuantity,String packMultiple,long priceBookRevision,Instant validUntil){}
 public record QuoteInput(UUID cartId,UUID addressId,UUID carrierQuoteId,String couponCode){}
 public record Line(UUID skuId,String quantity,String unitAmount,String lineTotal){}
 public record Totals(String subtotal,String discount,String tax,String delivery,String grandTotal){}
 public record Quote(UUID id,long cartVersion,String currency,List<Line> lines,Totals totals,String quoteHash,Instant expiresAt){}
 public record MinimumRule(UUID skuId,String minimumQuantity,String packMultiple,String minimumOrderAmount){}
 public record AssignmentInput(UUID marketId,UUID priceBookId,List<MinimumRule> minimumRules){public AssignmentInput{minimumRules=List.copyOf(minimumRules);}}
 public record Assignment(UUID organizationId,UUID priceBookId,long revision){}
 public record Components(BigDecimal subtotal,BigDecimal discount,BigDecimal tax,BigDecimal total){}
 public static Problem.Failure rule(){return new Problem.Failure(ProblemCode.PRICING_RULE_VIOLATION);}
 public static String currency(String value){if(value==null||!value.matches("[A-Z]{3}"))throw ApiValues.invalid();try{Currency.getInstance(value);}catch(IllegalArgumentException invalid){throw ApiValues.invalid();}return value;}
 private static String text(JsonNode n,String key,int min,int max){return MarketValues.text(n,key,min,max);}
 private static String raw(JsonNode n,String key,int min,int max){var value=n.get(key);if(value==null||!value.isString()||value.asString().length()<min||value.asString().length()>max)throw ApiValues.invalid();return value.asString();}
 private static void closed(JsonNode n,Set<String> required,Set<String> optional){if(n==null||!n.isObject()||!n.propertyNames().containsAll(required)||!java.util.stream.Stream.concat(required.stream(),optional.stream()).collect(java.util.stream.Collectors.toSet()).containsAll(n.propertyNames()))throw ApiValues.invalid();}
 public static Input input(JsonNode n,boolean create){var required=new HashSet<>(Set.of("currency","segment","effectiveFrom","entries"));if(create)required.add("code");closed(n,required,Set.of("effectiveUntil"));String code=create?text(n,"code",1,60):null;String curr=currency(raw(n,"currency",3,3)),segment=raw(n,"segment",6,11);if(!Set.of("RETAIL","DISTRIBUTOR").contains(segment))throw ApiValues.invalid();Instant from=ApiValues.instant(raw(n,"effectiveFrom",1,40)),until=n.has("effectiveUntil")?ApiValues.instant(raw(n,"effectiveUntil",1,40)):null;if(until!=null&&!until.isAfter(from))throw rule();var items=n.get("entries");if(!items.isArray()||items.isEmpty()||items.size()>100)throw ApiValues.invalid();var entries=new ArrayList<Entry>();var keys=new HashSet<String>();for(var item:items){closed(item,Set.of("skuId","minimumQuantity","unitAmount"),Set.of());UUID sku=ApiValues.uuid(raw(item,"skuId",36,36));BigDecimal qty=ApiValues.quantity(raw(item,"minimumQuantity",1,21));BigDecimal money=ApiValues.money(raw(item,"unitAmount",1,20),true);if(!keys.add(sku+":"+decimal(qty)))throw rule();entries.add(new Entry(sku,decimal(qty),money.toPlainString()));}entries.sort(Comparator.comparing((Entry e)->e.skuId().toString()).thenComparing(e->new BigDecimal(e.minimumQuantity())));return new Input(code,curr,segment,from,until,entries);}
 public static String reason(JsonNode n){closed(n,Set.of("reason"),Set.of());return text(n,"reason",10,300);}
 public static AssignmentInput assignment(JsonNode n){closed(n,Set.of("marketId","priceBookId","minimumRules"),Set.of());var rows=n.get("minimumRules");if(!rows.isArray()||rows.size()>100)throw ApiValues.invalid();var result=new ArrayList<MinimumRule>();var keys=new HashSet<String>();for(var row:rows){closed(row,Set.of(),Set.of("skuId","minimumQuantity","packMultiple","minimumOrderAmount"));if(row.isEmpty())throw ApiValues.invalid();UUID sku=row.has("skuId")?ApiValues.uuid(raw(row,"skuId",36,36)):null;String key=sku==null?"*":sku.toString();if(!keys.add(key))throw rule();String minimum=row.has("minimumQuantity")?decimal(ApiValues.quantity(raw(row,"minimumQuantity",1,21))):null;String pack=row.has("packMultiple")?decimal(ApiValues.quantity(raw(row,"packMultiple",1,21))):null;String amount=row.has("minimumOrderAmount")?ApiValues.money(raw(row,"minimumOrderAmount",1,20),true).toPlainString():null;result.add(new MinimumRule(sku,minimum,pack,amount));}return new AssignmentInput(ApiValues.uuid(raw(n,"marketId",36,36)),ApiValues.uuid(raw(n,"priceBookId",36,36)),List.copyOf(result));}
 public static QuoteInput quoteInput(JsonNode n){closed(n,Set.of("cartId","addressId","carrierQuoteId"),Set.of("couponCode"));String code=n.has("couponCode")?raw(n,"couponCode",1,80):null;if(code!=null&&!code.matches("[A-Za-z0-9_-]{1,80}"))throw ApiValues.invalid();return new QuoteInput(ApiValues.uuid(raw(n,"cartId",36,36)),ApiValues.uuid(raw(n,"addressId",36,36)),ApiValues.uuid(raw(n,"carrierQuoteId",36,36)),code);}
 public static String decimal(BigDecimal n){return n.stripTrailingZeros().toPlainString();}
 public static BigDecimal minor(String value,int scale){BigDecimal n=ApiValues.money(value,true);if(scale<0||scale>4||n.scale()>scale)throw rule();return n.setScale(scale);}
 public static BigDecimal quantity(String value,int scale){BigDecimal n=ApiValues.quantity(value);if(scale<0||scale>3||n.stripTrailingZeros().scale()>scale)throw rule();return n;}
 public static BigDecimal rounded(BigDecimal n,int scale){if(n==null||n.signum()<0||scale<0||scale>4)throw rule();var value=n.setScale(scale,RoundingMode.HALF_UP);if(value.compareTo(new BigDecimal("999999999999999.9999"))>0)throw rule();return value;}
 /** Discounts arrive as exact minor units, capped at the rounded pre-discount amount. */
 public static Components components(BigDecimal quantity,BigDecimal unit,BigDecimal discount,MarketValues.TaxPolicy tax,int scale){if(quantity==null||quantity.signum()<=0||unit==null||unit.signum()<0||discount==null||tax==null||!Set.of("NONE","EXCLUSIVE","INCLUSIVE").contains(tax.mode())||tax.rate()==null||tax.rate().signum()<0||tax.rate().compareTo(BigDecimal.ONE)>0||tax.mode().equals("NONE")&&tax.rate().signum()!=0)throw rule();BigDecimal before=rounded(quantity.multiply(unit),scale);if(discount.signum()<0||discount.scale()>scale||discount.compareTo(before)>0)throw rule();BigDecimal after=before.subtract(discount);if(tax.mode().equals("INCLUSIVE")){BigDecimal divisor=BigDecimal.ONE.add(tax.rate());BigDecimal baseBefore=before.divide(divisor,scale,RoundingMode.HALF_UP),baseAfter=after.divide(divisor,scale,RoundingMode.HALF_UP);return new Components(baseBefore,baseBefore.subtract(baseAfter),after.subtract(baseAfter),after);}BigDecimal levy=tax.mode().equals("NONE")?BigDecimal.ZERO.setScale(scale):rounded(after.multiply(tax.rate()),scale);return new Components(before,discount,levy,rounded(after.add(levy),scale));}
 /** Largest remainder allocation with canonical PostgreSQL UUID order as the deterministic tie-break. */
 public static Map<UUID,BigDecimal> allocate(Map<UUID,BigDecimal> amounts,BigDecimal discount,int scale){if(scale<0||scale>4||amounts==null||amounts.isEmpty()||amounts.size()>100||discount==null||discount.signum()<0||discount.scale()>scale)throw rule();BigInteger total=BigInteger.ZERO;var units=new TreeMap<UUID,BigInteger>(Comparator.comparing(UUID::toString));for(var e:amounts.entrySet()){if(e.getKey()==null||e.getKey().equals(new UUID(0,0))||e.getValue()==null||e.getValue().signum()<0||e.getValue().scale()>scale)throw rule();BigInteger value=e.getValue().movePointRight(scale).toBigIntegerExact();units.put(e.getKey(),value);total=total.add(value);}BigInteger target=discount.movePointRight(scale).toBigIntegerExact();if(target.compareTo(total)>0)throw rule();var allocated=new HashMap<UUID,BigInteger>();var remainders=new HashMap<UUID,BigInteger>();BigInteger used=BigInteger.ZERO;for(var e:units.entrySet()){BigInteger[] pair=total.signum()==0?new BigInteger[]{BigInteger.ZERO,BigInteger.ZERO}:target.multiply(e.getValue()).divideAndRemainder(total);allocated.put(e.getKey(),pair[0]);remainders.put(e.getKey(),pair[1]);used=used.add(pair[0]);}int extra=target.subtract(used).intValueExact();var order=units.keySet().stream().sorted(Comparator.<UUID,BigInteger>comparing(remainders::get).reversed().thenComparing(UUID::toString)).toList();for(int i=0;i<extra;i++)allocated.compute(order.get(i),(id,v)->v.add(BigInteger.ONE));var result=new LinkedHashMap<UUID,BigDecimal>();for(UUID id:units.keySet())result.put(id,new BigDecimal(allocated.get(id),scale));return Collections.unmodifiableMap(result);}
}
